window.MONSTER_CHUNK_105 = [{"name":"Cthulhu","cr":30,"xp":9830400,"alignment":"CE","size":"Colossal","type":"aberration","subtypes":["chaotic","evil","Great Old One"],"init":15,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"auras":["unspeakable presence (300 ft., DC 40)"],"ac":49,"ac_touch":29,"ac_flat_footed":44,"ac_mods":"+12 deflection, +5 Dex, +10 insight, +20 natural, -8 size","hp":774,"hd":"36d8+612","hdvalue":36,"hp_mods":["fast healing 30"],"fort":29,"ref":29,"will":33,"defensive_abilities":["freedom of movement","immortality","insanity (DC 40)","non-euclidean"],"dr":"20/epic and lawful","immunities":["ability damage","ability drain","aging","cold","death effects","disease","energy drain","mind-affecting effects","paralysis","and petrification"],"resists":[{"type":"acid","value":30},{"type":"electricity","value":30},{"type":"fire","value":30},{"type":"sonic","value":30}],"sr":41,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"2 claws +42 (4d6+23/19-20 plus grab), 4 tentacles +42 (2d10+34/19-20 plus grab)","space":"40 ft.","reach":"40 ft.","special_attacks":[{"type":"cleaving claws"},{"type":"constrict","details":"3d6+23"},{"type":"dreams of madness"},{"type":"mythic power","details":"10/day, surge +1d12"},{"type":"powerful blows","details":"tentacle"},{"type":"tentacles"},{"type":"trample","details":"2d8+30, DC 51"}],"spell_like_abilities_caster_level":30,"spell_like_abilities_concentration":47,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"insanity"},{"spell":"mythic control weather"},{"spell":"mythic dream"},{"spell":"mythic nightmare"},{"spell":"mythic sending"}]},{"frequency":"1/day","spells":[{"spell":"implosion"},{"spell":"mythic wish"},{"spell":"summon","details":"level 9, 2d4 star-spawn of Cthulhu 100%"},{"spell":"symbol of insanity"}]},{"frequency":"3/day","spells":[{"spell":"antipathy"},{"spell":"demand"},{"spell":"gate"},{"spell":"quickened feeblemind"},{"spell":"weird"}]}],"strength":56,"dexterity":21,"constitution":45,"intelligence":31,"wisdom":36,"charisma":34,"baseatk":27,"cmb":58,"cmb_special":"+2 vs. bull rush, +4 vs. grapple, +4 vs. sunder","cmd":97,"cmd_special":"+2 vs. bull rush, +2 vs. sunder","feats":[{"feat":"Ability Focus (nightmare)"},{"feat":"Awesome Blow"},{"feat":"Combat Reflexes"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Flyby Attack"},{"feat":"Greater Sunder"},{"feat":"Greater Vital Strike"},{"feat":"Hover"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Critical (tentacle)"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (feeblemind)"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":36},{"skill":"Knowledge (arcana)","value":49},{"skill":"Knowledge (dungeoneering, engineering, geography, history, nature, planes, religion)","value":46},{"skill":"Perception","value":52},{"skill":"Sense Motive","value":49},{"skill":"Spellcraft","value":49},{"skill":"Swim","value":70},{"skill":"Use Magic Device","value":48}],"languages":["Aklo","telepathy 300 ft."],"sq":[{"type":"compression"},{"type":"greater starflight"},{"type":"otherworldly insight"}],"environments":["any (R'lyeh)"],"organizations":["solitary (unique)"],"treasure":"triple","description_visual":"This towering impossibility, neither quite octopus nor dragon nor giant but something far worse, must surely herald the end of times.","group":"Great Old One","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Cleaving Claws","kind":"Ex","details":"A single attack from one of Cthulhu's claws can target all creatures in a 10-foot square. Make one attack roll; any creature in the area whose AC is equal to or lower than the result takes damage from the claw."},{"type":"Dreams of Madness","kind":"Su","details":"When Cthulhu uses his nightmare spell-like ability on a creature with one or more ranks in a Craft or Perform skill, he also afflicts the creature with maddening dreams. In addition to the effect of nightmare, the target must succeed at a DC 40 Will save or contract a random insanity. This is a mind-affecting effect. A creature that already has an insanity is immune to this ability. The save DC is Charisma-based."},{"type":"Greater Starflight","kind":"Su","details":"Cthulhu can survive in the void of outer space, and flies through outer space at incredible speeds. Although the exact travel time will vary from one trip to the next, a trip within a solar system normally takes Cthulhu 2d6 hours, and a trip beyond normally takes 2d6 days (or more, at the GM's discretion)."},{"type":"Immortality","kind":"Ex","details":"If Cthulhu is killed, his body immediately fades away into a noxious cloud of otherworldly vapor that fills an area out to his reach. This cloud blocks vision as obscuring mist, but can't be dispersed by any amount of wind. Any creature in this area must succeed at a DC 45 Fortitude save or be nauseated for as long as it remains in the cloud and for an additional 1d10 rounds after it leaves the area. Cthulhu returns to life after 2d6 rounds, manifesting from the cloud and restored to life via true resurrection, but is staggered for 2d6 rounds (nothing can remove this staggered effect). If slain again while he is staggered from this effect, Cthulhu reverts to vapor form again and his essence fades away after 2d6 rounds, returning to his tomb in R'lyeh until he is released again. The save DC is Constitution-based."},{"type":"Non-Euclidean","kind":"Ex","details":"Cthulhu doesn't exist wholly in the physical world, and space and time strain against his presence. This grants Cthulhu a deflection bonus to AC and a racial bonus on Reflex saves equal to his Charisma modifier (+12). His apparent and actual position are never quite the same, granting him a 50% miss chance against all attacks. True seeing can defeat this miss chance, but any creature that looks upon Cthulhu while under the effects of true seeing must succeed at a DC 40 Will save or be afflicted by a random insanity (this is a mind-affecting effect). The save DC is Charisma-based."},{"type":"Tentacles","kind":"Ex","details":"Cthulhu's tentacles are a primary attack."},{"type":"Unspeakable Presence","kind":"Su","details":"Failing a DC 40 Will save against Cthulhu's unspeakable presence causes the victim to immediately die of fright. This is a death and fear effect. A creature immune to fear that fails its save against Cthulhu's unspeakable presence is staggered for 1d6 rounds instead of killed. The save DC is Charisma-based."}],"description":"Known to some as the Dreamer in the Deep, Great Cthulhu is the mightiest of the Great Old Ones. Cthulhu is represented often in artwork-particularly in sculpture, painting, and poetry, for his influence is particularly strong among such sensitive and creative minds. In these eldritch works of art, he is depicted or described as having a vaguely humanoid frame, but with immense draconic wings and an octopus-shaped head. His actual form is somewhat fluid-the Great Old One can shift and reshape his exact countenance as he wills, allowing him to occupy a smaller space than one might expect for a creature that stands over 100 ft. tall. It is fortunate indeed that Cthulhu is currently imprisoned on a distant planet within the sunken city of R'lyeh. There, the Great Old One slumbers away the eons in a state neither quite dead nor living, held in stasis by ancient magic and the potency of the Elder Sign, yet at times the city rises from the sea and the doors to his tomb open, granting Cthulhu limited mobility before he must return to his tomb.\n\nCTHULHU'S CULT Although Cthulhu is imprisoned on a far-f lung world, his dreams span the gulfs of existence and are capable of touching upon the sleeping minds of sensitive or artistic souls, inspiring them with insane visions and driving the creation of all manner of eldritch artistry. In such ways, his cult spreads like a night-borne virus of the dreaming mind across all worlds on which sapient life dwells. Cthulhu is worshiped by various aquatic races and folk who dwell along coasts, but also among certain decadent or fringe societies of artists, poets, and philosophers. When they form, his cults are secretive and careful to hide their allegiance to the Great Old One, meeting only in desolate and otherwise abandoned locales hidden from society's notice. Central among his cult's beliefs is the prophecy that one day.","ecology":"","habitat_society":""},{"name":"Nocticula","cr":30,"xp":9830400,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"see in darkness"},{"type":"true seeing"}],"auras":["seductive presence (180 ft., DC 43)","unholy aura (DC 33)"],"ac":48,"ac_touch":41,"ac_flat_footed":35,"ac_mods":"+4 deflection, +13 Dex, +7 natural, +14 profane","hp":774,"hd":"36d10+576","hdvalue":36,"hp_mods":["regeneration 30 (deific or mythic)"],"fort":32,"ref":37,"will":35,"defensive_abilities":["Abyssal resurrection","freedom of movement"],"dr":"20/cold iron, epic, and lawful","immunities":["ability damage and drain","charm and compulsion effects","death effects","electricity","energy drain","fire","petrification","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30}],"sr":41,"speed":[{"type":"land","speed":60},{"type":"fly","speed":90,"maneuverability":"good"}],"melee":"2 claws +48 (1d8+12 plus 1d4 Cha drain), 3 stings +48 (2d6+12/19-20 plus poison), 2 hooves +43 (1d4+6 plus 1d6 fire and burn), 2 wings +43 (1d4+6)","ranged":"Shadowkiss +54 (1d4+20/17-20 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"3d6 fire, DC 44"},{"type":"cruel shot"},{"type":"domination"},{"type":"energy drain"},{"type":"poison"},{"type":"profane ascension"},{"type":"sneak attack","details":"+4d6"}],"spell_like_abilities_caster_level":30,"spell_like_abilities_concentration":46,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"tongues"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"chaos hammer"},{"spell":"deeper darkness"},{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"power word blind"},{"spell":"shapechange"},{"spell":"telekinesis"},{"spell":"unhallow"}]},{"frequency":"1/day","spells":[{"spell":"soul bind"},{"spell":"time stop"},{"spell":"wail of the banshee"}]},{"frequency":"3/day","spells":[{"spell":"finger of death"},{"spell":"quickened mass suggestion"},{"spell":"summon demons"},{"spell":"symbol of death"}]}],"strength":34,"dexterity":36,"constitution":42,"intelligence":35,"wisdom":32,"charisma":40,"baseatk":36,"cmb":48,"cmd":89,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Deadly Aim"},{"feat":"Flyby Attack"},{"feat":"Greater Feint"},{"feat":"Improved Critical (hand crossbow)"},{"feat":"Improved Critical (sting)"},{"feat":"Improved Feint"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Quicken Spell-Like Ability (mass suggestion)"},{"feat":"Rapid Reload (hand crossbow)"},{"feat":"Rapid Shot"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Acrobatics","value":52},{"skill":"Bluff","value":62},{"skill":"Diplomacy","value":54},{"skill":"Disguise","value":51},{"skill":"Fly","value":56},{"skill":"Intimidate","value":51},{"skill":"Knowledge (arcana, local, nobility)","value":48},{"skill":"Knowledge (planes, religion)","value":51},{"skill":"Perception","value":58},{"skill":"Perform (dance)","value":51},{"skill":"Sense Motive","value":50},{"skill":"Sleight of Hand","value":49},{"skill":"Spellcraft","value":48},{"skill":"Stealth","value":52},{"skill":"Use Magic Device","value":54}],"languages":["Abyssal","Celestial","Common","Draconic","Undercommon","telepathy 300 ft.","tongues"],"sq":[{"type":"change shape","details":"any humanoid; alter self"},{"type":"swift transformation"}],"environments":["any (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple (Shadowkiss, 100,000 gp in various jewelry)","description_visual":"This frighteningly majestic creature spreads wide her rune-adorned wings. Molten iron weeps from her hooves, and her three tails are studded with barbs.","group":"Demon Lord","source":"AP 76","special_abilities":[{"type":"Cruel Shot","kind":"Ex","details":"Nocticula is adept at making ranged attacks to strike cruel shots that deal significant and humiliating damage. She adds her Charisma bonus to all damage dealt by ranged weapons."},{"type":"Domination","kind":"Su","details":"As a standard action, Nocticula can crush a foe's will. The target must be visible to Nocticula and within 120 ft. It must succeed at a DC 43 Will save or fall instantly under Nocticula's influence as dominate monster (CL 30th). If she uses domination against a humanoid creature, she may instead choose to use the ability as a swift action, and it functions as dominate person. As long as the target is under this effect, it gains a +4 profane bonus on all saving throws against targets other than Nocticula."},{"type":"Energy Drain","kind":"Su","details":"Nocticula's energy drain functions identically to that of a succubus, except that she drains 2 levels when she uses this ability against mythic creatures, or 1d6+4 levels against non-mythic creatures."},{"type":"Poison","kind":"Ex","details":"Sting or hand crossbow-injury; save Fort DC 44; frequency 1/round for 6 rounds; effect 1d4 Wisdom drain plus paralysis for 1 round. Anyone who fails two consecutive saves against this poison is permanently blinded. The save DC is Constitution-based."},{"type":"Profane Ascension","kind":"Su","details":"As a swift action while in an act of passion with a willing mortal, Nocticula may grant a profane ascension. The target's name appears in glowing Abyssal runes on Nocticula's wings, and a crimson mark manifests somewhere on the target's body. The target immediately gains a +6 profane bonus to any one ability score of its choice, a +4 profane bonus to any other ability score of its choice, and the see in darkness ability. A single creature may have only one profane ascension in effect at any one time. As long as the effect persists, Nocticula can communicate telepathically with the target across any distance and may use any of her spell-like abilities through the target, manifesting them as if the target were using them. A profane ascension may be removed by a miracle or wish. Nocticula can remove it as a free action, dealing 4d6 points of Charisma drain and imparting 1d10+10 permanent negative levels to the victim."},{"type":"Seductive Presence","kind":"Su","details":"Unlike most demon lords, Nocticula doesn't possess a frightful presence ability. Rather, she has a seductive presence that she can activate as a free action whenever she speaks or uses a spell-like ability. Anyone within 180 ft. who fails a DC 43 Fortitude save loses any immunity to mind-affecting effects, charm effects, and compulsion effects, and becomes fascinated by Nocticula for 5d4 rounds. A creature affected by a mind-affecting effect while within this aura remains affected even after leaving Nocticula's seductive presence. Creatures that succeed at this saving throw are immune to this ability for 24 hours. The save DC is Charisma-based. Shadowkiss Nocticula's favored weapon is Shadowkiss, a +5 unholy hand crossbow that magically creates ammunition as it fires. Once a target is damaged by a bolt fired from Shadowkiss, the hand crossbow gains the bane weapon special ability against that target's creature type on all further attacks. Shadowkiss may only have one bane effect in place at one time. Bolts fired from Shadowkiss gain the ghost touch ability (an effect not normally available to ranged weapons)."},{"type":"Swift Transformation","kind":"Ex","details":"Nocticula can use her change shape ability as a free action."}],"description":"Nocticula is the demon lord of assassins, darkness, and lust, and rules the Abyssal realm of the Midnight Isles, a vast archipelago formed around the murdered remnants of dozens of demon lords and other powerful foes. Having been the first succubus and then having ascended to become a demigoddess, Nocticula now sets her eyes at a greater prize-full divinity. Lamashtu is the only demon lord who has accomplished this task so far, but Nocticula aims to be the second. What kind of deity she might become is anyone's guess-some believe that Nocticula is secretly seeking redemption from her demonic nature. Others say these rumors were seeded by Nocticula herself as a grand lie to distract her enemies from her true goal of becoming an assassin and seducer of gods.\n\nNocticula is certainly mercurial in her personality and attitude. She may simply murder or enslave visitors to her realm, or she may welcome them with open arms-even those who one would think were her enemies. Only a fool accepts her invitation without suspicion, for what the queen of succubi wants may change dramatically from one moment to the next.\n\nNocticula's Cult\n\nNocticula is worshiped by assassins, the lustful, whores, shadow-using creatures, and of course succubi. These worshipers form relatively small cults, often akin to secret societies, that use brothels, nobility, or academies as a cover for their true purposes. A small number of heretics venerate her as well, not as a demigoddess of murder and lust but as one of outcasts, artists, and the glories of midnight. The fact that such heretical clerics are granted spells as surely as the rest of her worshipers has caused not a small amount of discontent among her faithful, which Nocticula seems to enjoy.\n\nNocticula's symbol is a multi-pointed crown wrapped with thorny vines. Her favored weapon is the hand crossbow. She grants access to the domains of Chaos, Charm, Darkness, and Evil, and to the subdomains of Demon, Loss, Lust, and Night.","ecology":"","habitat_society":""},{"name":"Pazuzu","cr":30,"xp":4915200,"alignment":"CE","size":"Large","type":"outsider","subtypes":["air","chaotic","demon","evil","extraplanar"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["frightful presence (180 ft., DC 40, 10 rounds)","locusts (10 ft., distraction, DC 43)","unholy aura (DC 31)"],"ac":48,"ac_touch":38,"ac_flat_footed":39,"ac_mods":"+4 deflection, +9 Dex, +10 natural, +16 profane, -1 size","hp":752,"hd":"35d10+560","hdvalue":35,"hp_mods":["regeneration (deific or mythic)"],"fort":31,"ref":32,"will":35,"defensive_abilities":["Abyssal resurrection","avian mastery","freedom of movement"],"dr":"20/cold iron, epic, and good","immunities":["ability damage","ability drain","charm effects","compulsion effects","cold","death effects","electricity","energy drain","petrification","and poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30}],"sr":41,"speed":[{"type":"land","speed":60},{"type":"fly","speed":150,"maneuverability":"perfect"}],"melee":"+5 anarchic keen unholy longsword +54 (2d6+20/17-20), bite +49 (2d6+15), claw +49 (1d6+15), sting +49 (2d8+15 plus poison), 2 talons +49 (1d6+15)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"hear name"},{"type":"poison"},{"type":"possession"},{"type":"profane wishcraft"},{"type":"swarm master"}],"spell_like_abilities_caster_level":30,"spell_like_abilities_concentration":46,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"speak with animals","details":"winged animals only"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"astral projection"},{"spell":"blasphemy"},{"spell":"control winds"},{"spell":"desecrate"},{"spell":"dominate person"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"shapechange"},{"spell":"telekinesis"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"dominate monster"},{"spell":"time stop"},{"spell":"wish"}]},{"frequency":"3/day","spells":[{"spell":"quickened dominate person"},{"spell":"summon demons"},{"spell":"symbol of persuasion"},{"spell":"sympathy"},{"spell":"whirlwind"}]}],"strength":40,"dexterity":28,"constitution":42,"intelligence":33,"wisdom":34,"charisma":36,"baseatk":35,"cmb":51,"cmb_special":"+4 vs. sunder","cmd":92,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Bleeding Critical"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Rod"},{"feat":"Craft Wondrous Item"},{"feat":"Critical Focus"},{"feat":"Flyby Attack"},{"feat":"Greater Sunder"},{"feat":"Greater Vital Strike"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (dominate person)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":47,"special":"+59 when jumping"},{"skill":"Bluff","value":51},{"skill":"Diplomacy","value":51},{"skill":"Fly","value":53},{"skill":"Intimidate","value":48},{"skill":"Knowledge (arcana)","value":49},{"skill":"Knowledge (local)","value":46},{"skill":"Knowledge (nature)","value":46},{"skill":"Knowledge (nobility)","value":46},{"skill":"Knowledge (planes)","value":49},{"skill":"Knowledge (religion)","value":46},{"skill":"Perception","value":58},{"skill":"Sense Motive","value":50},{"skill":"Spellcraft","value":49},{"skill":"Stealth","value":43},{"skill":"Survival","value":47},{"skill":"Use Magic Device","value":48}],"languages":["Abyssal","Auran","Celestial","Common","Draconic","telepathy 300 ft."],"sq":[{"type":"demon lord traits"}],"environments":["any (Abyss)"],"organizations":["solitary (unique)"],"treasure":"triple (Scepter of Shibaxet)","description_visual":"Held aloft by four great feathered wings, this hawk-faced fiend has a scorpion's tail and carries a black metal scepter.","group":"Demon Lord","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Aura of Locusts","kind":"Su","details":"Pazuzu exhales clouds of locusts. In any round in which he doesn't move more than 5 ft., he is surrounded by a 10-foot-radius spread of these creatures. Any creature that enters this area must succeed at a DC 43 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based."},{"type":"Avian Mastery","kind":"Su","details":"Any creature flying under its own power (flight from a source other than a spell, spell-like ability, or magic item) that attempts to attack Pazuzu with a melee attack must attempt a DC 40 Will save. If it fails, the creature can't follow through with the attack, that part of its action is lost, and it can't directly attack Pazuzu for 1d4 rounds. Once a creature succeeds at this save, it is immune to this ability for 24 hours. The save DC is Charisma-based."},{"type":"Hear Name","kind":"Su","details":"Pazuzu hears his name whenever it is spoken, regardless of distance-this ability functions even across planar boundaries. If a creature speaks Pazuzu's name aloud three times in the same breath, Pazuzu automatically knows that creature's precise location and name. If Pazuzu is on the same plane as someone who speaks his name three times in a single breath, he can immediately attempt to possess that creature."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 43; frequency 1/round for 6 rounds; effect 1d6 Wisdom drain and nauseated; cure 3 consecutive saves."},{"type":"Possession","kind":"Su","details":"Once per day as a swift action, Pazuzu can attempt to possess a single living creature within 1 mile, provided he knows the target's name. The target can resist this possession attempt by succeeding at a DC 43 Will save. A lawful creature gains a +10 bonus on this saving throw, and a good creature gains a +20 bonus on the saving throw (these bonuses stack). If the creature successfully saves, it is immune to possession attempts by Pazuzu for the rest of its life. If the saving throw fails, Pazuzu can control the possessed creature from afar. While possessing a creature, Pazuzu automatically knows every thought that creature has. By concentrating, he can sense the creature's surroundings using that creature's senses. As a swift action, he can cause the creature to perform any ability it can perform on its own. Pazuzu can use any of his spell-like abilities through a possessed target, with the effects resolving as if the possessed creature had created the effect. Possession is permanent, but Pazuzu can only possess one creature at a time. When Pazuzu isn't actively controlling the target, it can take its own actions. Dispel chaos or dispel evil ends this possession effect as if it were an enchantment spell, but unless the caster of the spell succeeds at a DC 30 caster level check, as a swift action Pazuzu can attempt to possess the caster as he is driven out of the target. A creature possessed by Pazuzu is immune to protection from evil, magic circle against evil, and any similar effects. The save DC is Charisma-based."},{"type":"Profane Wishcraft","kind":"Su","details":"A creature that accepts a wish from Pazuzu immediately becomes chaotic evil unless it succeeds at a DC 43 Will save. A creature that becomes chaotic evil in this way gains the benefits of a good hope spell for 1 week, followed by the effects of crushing despair for 1d6 months (CL 30th). The save DC is Charisma-based."},{"type":"Swarm Master","kind":"Su","details":"Pazuzu is immune to swarm damage and other swarm effects (such as distraction). As a swift action, he can direct the movement of any swarm within 30 ft."}],"description":"Pazuzu is among the oldest and most powerful of all demon lords. His Abyssal realm is located in one of that plane's greatest rifts. This vertical realm includes an immense city, at the heart of which can be found Shibaxet, Pazuzu's personal rookery and palace. Pazuzu appears as a four-winged, 15-foot-tall fiend. He takes great delight in corrupting mortals, particularly those of a pure heart and soul, offering them any one wish in return for nothing but their innocence.\n\nPAZUZU'S CULT\n\nPazuzu, King of the Wind Demons, is worshiped by harpies and other evil avians, and by a large number of antipaladins who were once honorable but were tempted to chaos and evil-often by Pazuzu himself. His sacred places and temples are cliffside cathedrals, desert ruins, and spires atop mountain peaks. His unholy symbol is an image of himself with his right hand upraised. His favored weapon is the longsword. He grants access to the domains of Air, Chaos, Evil, and Trickery, and access to the subdomains of Cloud, Deception, Demon, and Wind.","ecology":"","habitat_society":""},{"name":"Amanusya Rakshasa","cr":6,"xp":2400,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["native","rakshasa","shapechanger"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":66,"hd":"7d10+28","hdvalue":7,"fort":6,"ref":9,"will":6,"dr":"5/good or piercing","sr":21,"speed":[{"type":"land","speed":40}],"melee":"2 claws +11 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"detect thoughts","details":"DC 17"},{"type":"sneak attack","details":"+3d6"}],"strength":15,"dexterity":19,"constitution":18,"intelligence":12,"wisdom":13,"charisma":18,"baseatk":7,"cmb":9,"cmd":23,"feats":[{"feat":"Nimble Moves"},{"feat":"Skill Focus (Perform [dance])"},{"feat":"Step Up"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Acrobatics (jumping)","value":18},{"skill":"Bluff","value":18},{"skill":"Disguise","value":22},{"skill":"Escape Artist","value":14},{"skill":"Perception","value":11},{"skill":"Perform (dance)","value":17},{"skill":"Stealth","value":14}],"languages":["Common","Infernal","Undercommon"],"sq":[{"type":"beguiling dance"},{"type":"change shape","details":"any humanoid; alter self"},{"type":"swift change"}],"environments":["any"],"organizations":["solitary","pair","troupe (3-8)"],"treasure":"standard","description_visual":"This lithe, graceful dancer would almost be beautiful, if not for her clawed hands, a head that faces backward, and an unnaturally long, lolling tongue.","group":"Rakshasa","source":"Pathfinder Campaign Setting: Occult Bestiary","special_abilities":[{"type":"Beguiling Dance","kind":"Ex","details":"An amanusya may substitute a Perform (dance) check for a concentration check made to cast defensively, or for an Acrobatics check made to move through a threatened square. Once per round, succeeding at such a check to slip through a threatened square lets her immediately attempt a free feint against that foe."},{"type":"Swift Change","kind":"Su","details":"An amanusya can change shape as a swift action, but only when she is reverting to her true form."},{"type":"Psychic Magic","details":"An amanusya draws on a pool of 5 points of psychic energy (CL 4th; concentration +8) to fuel the following spells: babble (2 points, DC 16), blur (2 points), deja vu (1 point, DC 15), hideous laughter (1 point, DC 15), hold person (2 points, DC 16), hypnotism (1 point, DC 15), id insinuation I (2 points, DC 16), and paranoia (1 point, DC 15)."}],"description":"Amanusyas are among the most sociable rakshasas, moving freely through mortal society while studying people's hopes and weaknesses so they can be turned to ruin. Posing as performers or as holy figures from far-off traditions, they patiently cultivate a target's trust for months before striking, offering false promises of fame, fortune, or a better life to lure victims toward ever greater betrayals. They favor cities, where crowded markets, theaters, and festivals let them watch prey unnoticed, and they often set up in the former homes of past victims. Though they resent taking orders from stronger rakshasas, amanusyas sometimes band together in small troupes for safety, and a rare few are even said to fall genuinely in love with a mortal, invariably to tragic effect. Only humanoids of Medium size can father amanusya offspring; most amanusyas are female, standing around five and a half feet tall and weighing roughly 120 pounds.","ecology":"","habitat_society":""},{"name":"Avatarana Rakshasa","cr":12,"xp":19200,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["native","rakshasa","shapechanger"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":26,"ac_touch":15,"ac_flat_footed":21,"ac_mods":"+4 Dex, +1 dodge, +11 natural","hp":157,"hd":"15d10+75","hdvalue":15,"fort":14,"ref":11,"will":11,"defensive_abilities":["absolute independence"],"dr":"15/good and piercing","sr":27,"speed":[{"type":"land","speed":40}],"melee":"4 claws +21 (1d6+6 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"corporeal possession"},{"type":"detect thoughts","details":"DC 21"}],"strength":22,"dexterity":19,"constitution":20,"intelligence":13,"wisdom":14,"charisma":19,"baseatk":15,"cmb":21,"cmb_special":"+29 grapple","cmd":36,"cmd_special":"38 vs. grapple","feats":[{"feat":"Dodge"},{"feat":"Greater Grapple"},{"feat":"Heighten Spell"},{"feat":"Improved Grapple"},{"feat":"Improved Initiative"},{"feat":"Improved Unarmed Strike"},{"feat":"Lightning Reflexes"},{"feat":"Step Up"}],"skills":[{"skill":"Bluff","value":26},{"skill":"Diplomacy","value":22},{"skill":"Disguise","value":30},{"skill":"Knowledge (religion)","value":19},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":20},{"skill":"Stealth","value":22}],"languages":["Common","Infernal","Undercommon","telepathy 100 ft."],"sq":[{"type":"change shape","details":"any humanoid; alter self"}],"environments":["any"],"organizations":["solitary","cult (1 plus 6-36 humanoid followers)"],"treasure":"standard","description_visual":"In place of legs, this bald, wasted humanoid stands on a second pair of long, muscular arms, its face hidden behind a taut leathery flap.","group":"Rakshasa","source":"Pathfinder Campaign Setting: Occult Bestiary","special_abilities":[{"type":"Absolute Independence","kind":"Ex","details":"An avatarana cannot be affected by charm or compulsion spells and effects, nor by magic jar, possession, or similar magic."},{"type":"Corporeal Possession","kind":"Su","details":"As a full-round action that provokes attacks of opportunity, an avatarana can flow into the body of an adjacent pinned, helpless, or willing humanoid, taking control of it as though using greater possession. When it later withdraws, it reforms in an open space next to its former host."}],"description":"Avatarana push the rakshasa race's distortion of the humanoid shape to its most disturbing extreme, with gangly, ill-fitting limbs that nonetheless move with startling speed and grace. Every avatarana's face is sealed behind a strip of leathery flesh that cannot be removed by ordinary means; onlookers often feel that their own features stir beneath it, and even investigators who manage to cut the covering away find only hollow, shifting cavities beneath. Rather than confronting victims directly, an avatarana merges its body into that of an unsuspecting mortal and drives it toward atrocities, climbing the social ladder by possessing ever more influential hosts and abandoning each once others turn against them. Ambitious and patient, they sometimes recruit lesser rakshasas or bands of human followers to handle tasks beneath a possessed host's dignity. Standing on its hind limbs, an avatarana reaches roughly six feet and weighs about 125 pounds.","ecology":"","habitat_society":""},{"name":"Orsatka Rakshasa","cr":13,"xp":25600,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["native","rakshasa","shapechanger"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":28,"ac_touch":16,"ac_flat_footed":22,"ac_mods":"+6 Dex, +12 natural","hp":189,"hd":"14d10+112","hdvalue":14,"fort":17,"ref":15,"will":11,"dr":"15/good and piercing","sr":28,"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"bite +23 (4d6+9/19-20 plus stagger), 2 claws +23 (2d4+9 plus stagger)","space":"5 ft.","reach":"5 ft. (10 ft. with trip)","special_attacks":[{"type":"detect thoughts","details":"DC 23"},{"type":"wicked reach"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"magic missile"}]},{"frequency":"1/day","spells":[{"spell":"true form (DC 18)"}]},{"frequency":"3/day","spells":[{"spell":"dispel magic"},{"spell":"magic circle against good"}]}],"strength":28,"dexterity":22,"constitution":26,"intelligence":15,"wisdom":21,"charisma":19,"baseatk":14,"cmb":23,"cmb_special":"+27 trip","cmd":39,"cmd_special":"41 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Greater Trip"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Trip"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":25},{"skill":"Climb","value":34},{"skill":"Disguise","value":29},{"skill":"Intimidate","value":21},{"skill":"Knowledge (local, planes)","value":12},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":26},{"skill":"Stealth","value":23}],"languages":["Common","Infernal","Undercommon"],"sq":[{"type":"change shape","details":"any humanoid; alter self"}],"environments":["any"],"organizations":["solitary","guard (1 plus 1 other rakshasa)"],"treasure":"double","description_visual":"This hulking, bear-headed fiend bares a mouthful of fangs, its clawed, six-fingered hands bristling with too many knuckles.","group":"Rakshasa","source":"Pathfinder Roleplaying Game: Book of the Damned","special_abilities":[{"type":"Stagger","kind":"Su","details":"A creature hurt by an orsatka's bite or claw must succeed at a DC 21 Will save (Charisma-based) or be staggered for 1 round by the searing pain; this is a mind-affecting pain effect."},{"type":"Wicked Reach","kind":"Ex","details":"An orsatka's unnaturally jointed limbs let it attempt trip combat maneuvers as though it had 10 ft. of reach, and it can make such trip attempts as attacks of opportunity."}],"description":"Nicknamed \"fiend killers,\" orsatkas are among the bluntest of rakshasas, born from lives of large-scale, senseless brutality. Rather than relying on spellcraft, they channel their kind's usual magical affinity into an unerring sense for locating hidden enemies, and they make up for what they lack in subtlety with sheer punishing force. In their natural state they resemble massive, muscular humans with the heads of bears, sometimes covered in coarse, reddish fur. A full-grown orsatka stands around 7 feet tall and weighs close to 400 pounds.","ecology":"","habitat_society":""},{"name":"Zalyakavat Rakshasa","cr":13,"xp":25600,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["native","rakshasa","shapechanger"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":28,"ac_touch":17,"ac_flat_footed":21,"ac_mods":"+6 Dex, +1 dodge, +11 natural","hp":178,"hd":"17d10+85","hdvalue":17,"fort":15,"ref":16,"will":11,"dr":"15/good and piercing","sr":28,"speed":[{"type":"land","speed":40}],"melee":"+2 urumi +24/+19/+14/+9 (1d8+6/15-20)","space":"5 ft.","reach":"5 ft. (10 ft. with urumi)","special_attacks":[{"type":"detect thoughts","details":"DC 20"},{"type":"urumi forms"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":10,"spellsknown_concentration":15,"spellsknown":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"wall of stone (DC 17)"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"dimension door"},{"spell":"ice storm"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic"},{"spell":"lightning bolt (DC 15)"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blur"},{"spell":"darkness"},{"spell":"knock"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"expeditious retreat"},{"spell":"identify"},{"spell":"mage armor"},{"spell":"magic aura"},{"spell":"ray of enfeeblement (DC 13)"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed (DC 12)"},{"spell":"detect magic"},{"spell":"ghost sound (DC 12)"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"open/close"},{"spell":"read magic"}]}],"strength":19,"dexterity":22,"constitution":21,"intelligence":16,"wisdom":18,"charisma":15,"baseatk":17,"cmb":21,"cmd":38,"feats":[{"feat":"Acrobatic Steps"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Critical (urumi)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Nimble Moves"},{"feat":"Quick Draw"},{"feat":"Weapon Focus (urumi)"}],"skills":[{"skill":"Acrobatics","value":26},{"skill":"Acrobatics (jumping)","value":30},{"skill":"Bluff","value":26},{"skill":"Disguise","value":30},{"skill":"Knowledge (arcana, local)","value":23},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":24},{"skill":"Spellcraft","value":20},{"skill":"Stealth","value":26}],"languages":["Common","Infernal","Undercommon"],"sq":[{"type":"change shape","details":"any humanoid; alter self"},{"type":"inconspicuous urumi"},{"type":"urumi affinity"}],"environments":["any"],"organizations":["solitary","pair","muster (3-6)"],"treasure":"standard (+2 urumi, other treasure)","description_visual":"This sinewy, putrid-green humanoid has a grotesque, shrew-like snout and wears little beyond a bright silk sarong and a thin, flexible blade worn coiled as a belt.","group":"Rakshasa","source":"Pathfinder Adventure Path #130: City in the Lion's Eye","special_abilities":[{"type":"Inconspicuous Urumi","kind":"Su","details":"A zalyakavat can carry an urumi in its belt slot and draw it as a free action. While worn there, the weapon's enhancement bonus, if any, also applies to the zalyakavat's Bluff and Disguise checks, and an urumi with a +2 or better enhancement bonus grants the benefit of nondetection at a caster level equal to the zalyakavat's own plus the weapon's bonus."},{"type":"Spellcasting","details":"A zalyakavat casts arcane spells as a 10th-level sorcerer."},{"type":"Urumi Affinity","kind":"Su","details":"A zalyakavat never drops its urumi when panicked or stunned, and treats its reach with the weapon as 5 feet greater than normal."},{"type":"Urumi Forms","kind":"Su","details":"As a swift action (forgoing spellcasting that round), a zalyakavat holding an urumi in one paw and nothing in the other can burn an unused spell slot to activate one of several urumi forms lasting until its next turn, each also granting freedom of movement until then: Contingent Strikes (1st-level slot or higher) temporarily imbues the urumi with a magic weapon special ability keyed to the slot's level, functioning only for the zalyakavat; Deft Strikes (2nd-level+) grants Improved Disarm and Improved Trip plus a competence bonus on disarm/trip checks equal to the slot's level; Dispelling Strikes (3rd-level+) subjects a struck creature to a targeted dispel magic; Garrote Whip (4th-level+) extends the urumi's reach by 5 feet and lets the zalyakavat attempt to strike and strangle a foe, dealing extra damage and risking 1d4 rounds of unconsciousness on a failed DC 22 Fortitude save; and Whip of Many Blades (5th-level slot) grants two extra attacks at the zalyakavat's highest base attack bonus on a full attack."}],"description":"Shrew-faced and hungry for a good fight, zalyakavats bind themselves body and soul to the urumi, a flexible whip-sword, and channel arcane power through the blade to perform astonishing feats of swordsmanship. They are born from the spirits of the cruelest and most dishonorable warriors, usually to a rakshasa mother, and even as infants they dream of the weapon they will one day master. Unlike most of their kind, zalyakavats crave violent combat more than wealth, though they remain cunning enough to stack the odds in their favor with guile and magic. They keep homes scattered across several cities, tailoring a disguise to whatever prey they favor hunting, and after a kill often take a trophy from the body to decorate their lair. Zalyakavats seldom mix with other rakshasas, occasionally serving as bodyguards to more powerful kin, and sometimes gather to stage secret duels using kidnapped mortals as unwilling combatants. A typical zalyakavat stands about 6-1/2 feet tall and weighs around 170 pounds.","ecology":"","habitat_society":""},{"name":"Quipper","cr":0.125,"xp":50,"alignment":"N","size":"Fine","type":"animal","subtypes":["aquatic"],"init":2,"senses":[{"type":"low-light vision"},{"type":"keen scent"}],"ac":20,"ac_touch":20,"ac_flat_footed":18,"ac_mods":"+2 Dex, +8 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":4,"will":1,"speed":[{"type":"swim","speed":30}],"melee":"bite +10 (1d2-2)","space":"1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"frenzy"}],"strength":6,"dexterity":15,"constitution":10,"intelligence":1,"wisdom":12,"charisma":3,"baseatk":0,"cmb":-6,"cmd":2,"cmd_special":"can't be tripped","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Perception","value":8},{"skill":"Swim","value":10}],"environments":["cold aquatic","temperate aquatic"],"organizations":["shoal (5-50)","school (50-100)"],"treasure":"none","description_visual":"This small fish has a mouth full of razor-sharp teeth and a vicious disposition.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Frenzy","kind":"Ex","details":"Quippers can detect blood in the water goes into a killing frenzy, as do all other quippers within a 90-foot radius. Frenzied quippers attack until either they or their opponents are dead. A frenzied quipper can make one extra attack when making a full attack action. The attack is made using the creature's full base attack. Additionally, it gains a +1 bonus on attack rolls and a +1 dodge bonus to AC and Reflex saves. A frenzied quipper's swim speed increases by 10 ft. This frenzy lasts for 1 minute and can only be used once per encounter."},{"type":"Keen Scent","kind":"Ex","details":"A quipper can notice creatures by scent in a 90-foot radius underwater and can detect blood in the water at ranges up to 500 ft."}],"description":"The quipper is a rare form of cold-water piranha. They are dark green in color and are found in freshwater lakes and stream.\n\nQuippers attack by swarming an opponent and biting with their razor-sharp teeth. Once blood is drawn, the entire pack goes into a frenzy, attacking twice each round.","ecology":"","habitat_society":"","credit":"The quipper originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Skunk","cr":0.125,"xp":50,"alignment":"N","size":"Tiny","type":"animal","init":1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":13,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":3,"will":1,"speed":[{"type":"land","speed":30}],"melee":"bite +3 (1d3-4)","ranged":"spray +4 touch (musk)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"musk"}],"strength":2,"dexterity":13,"constitution":10,"intelligence":2,"wisdom":13,"charisma":2,"baseatk":0,"cmb":0,"cmd":6,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":9}],"environments":["temperate forests","temperate hills"],"organizations":["solitary","family (2-5)"],"treasure":"none","description_visual":"This small, catlike creature has a coat of black fur punctuated by white stripes that travel the length of its body and bushy tail.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Musk","kind":"Ex","details":"Once per round, and no more than 5 times per day , a skunk can release a cloud of stinking musk that quickly fillsa 5-foot area in front of it. A creature within or entering the area must succeed on a DC 10 Fortitude save or be sickened for 1d4 rounds. One round later a second Fortitude save must be made (whether the first one succeeded or not) or the affected creature is blinded for 1d4 rounds. The save DCs are Constitution-based .A delay poison or neutralize poison spell removes the effect from the sickened creature, but doesn't remove the blindness. Creatures immune to poison are unaffected by the sickened effect but can still be blinded if they fail their save, and creatures resistant to poison receive their normal bonus on both saving throws. The stench is highly potent, and short of magical means of cleaning, all cloth and such material continue to reek for 1d6 months. The odor is so strong that it doubles all chances for random encounters and imposes a -6 penalty on Stealth checks attempted while wearing clothing contaminated with a skunk's musk. Flesh, leather goods, metal goods (weapons, armor, and the like) must be washed in a concentrated mixture of vinegar over period of 1d3 days . Otherwise, the stench clings for at least one week, imposing the same modifiers to random encounters and Stealth checks."}],"description":"The stats here describe the common nonaggressive skunk. Skunks squirt their musk at potential predators in hopes of forcing the predator to flee. If this fails, the skunk looks for the quickest route possible for itself to escape. If cornered, a skunk bites its opponents.","ecology":"","habitat_society":"","credit":"The Skunk originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Clockwork Drone","cr":0.1667,"xp":65,"alignment":"N","size":"Tiny","type":"construct","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":16,"ac_flat_footed":12,"ac_mods":"+4 Dex, +2 size","hp":5,"hd":"1d10","hdvalue":1,"fort":0,"ref":4,"will":2,"immunities":["construct traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"slam +0 (1d3-3)","space":"2-1/2 ft.","reach":"0 ft.","strength":5,"dexterity":18,"wisdom":14,"charisma":6,"baseatk":1,"cmb":3,"cmd":10,"cmd_special":"can't be tripped","skills":[{"skill":"Fly","value":16}],"environments":["any"],"organizations":["swarm (3-8)"],"treasure":"none","description_visual":"This creature appears as a human eyeball encased within a flat, metal disk.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Fly","kind":"Su","details":"A clockwork drone can cease or resume its flight as a free action."}],"description":"Imbued with magic that allows it to fly, a drone has an approach typically marked by the low buzz of its tiny gears and pistons, which work furiously to maintain the magical field that allows it to fly. These clockworks are designed to act as observers. When a drone finds an advantageous position from which to maintain its watch, it uses a small, metallic claw on its underside to attach itself to a surface.\n\nDrones usually avoid combat at all costs. When they are pressed into fighting, they prefer to aid their fellow clockworks by distracting their enemies.","ecology":"","habitat_society":""},{"name":"Killmoulis","cr":0.1667,"xp":65,"alignment":"CN","size":"Diminutive","type":"fey","init":3,"senses":[{"type":"low-light-vision"}],"ac":18,"ac_touch":18,"ac_flat_footed":14,"ac_mods":"+3 Dex, +1 dodge, +4 size","hp":4,"hd":"1d6+1","hdvalue":1,"fort":1,"ref":5,"will":4,"dr":"5/cold iron","sr":11,"speed":[{"type":"land","speed":40}],"melee":"needle +7 (1d2-3)","space":"1 ft.","reach":"0 ft.","strength":5,"dexterity":16,"constitution":12,"intelligence":10,"wisdom":14,"charisma":6,"baseatk":0,"cmb":-7,"cmd":7,"feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Craft (any one)","value":4},{"skill":"Escape Artist","value":7},{"skill":"Perception","value":8},{"skill":"Profession (farmer or miller)","value":4},{"skill":"Stealth","value":23}],"languages":["telepathy 100 ft."],"environments":["temperate forests","temperate underground"],"organizations":["solitary","gang (2-4)"],"treasure":"1/10 standard","description_visual":"A tiny, unnaturally thin humanoid frolics nearby. It has a huge bulbous head with no chin and seemingly no mouth. It has an immense trunk-like nose. Its skin is pale white and its eyes are deep blue.","source":"Tome of Horrors Complete (3pp)","description":"A killmoulis is thought to be distantly related to brownies and other small, helpful fey, though it bears little physical likeness to its kin.\n\nStanding about 1 foot tall, they don't speak except through a limited form of telepathy. The race appears to be sexless. A killmoulis gang always tries to take up residence in places of human habitation where foodstuffs are prepared or handled, dwelling beneath floorboards or in garrets or behind pantry shelves. The killmoulis has the same loyalty to its host family and eagerness to perform chores as the brownie, but unlike the brownie they are more prone to pointless but harmless mischief.\n\nKillmoulises are inoffensive creatures, lacking any real combat capability. They do carry dagger-like needles, however, and use these to stab and pierce their opponents. Occasionally, these needles are poisoned (with whatever poison is readily available).","ecology":"","habitat_society":"","credit":"The Killmoulis originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission.","gear":"sewing needle"},{"name":"Racoon","cr":0.1667,"xp":65,"alignment":"N","size":"Tiny","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":4,"will":1,"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"bite +4 (1d3-3)","space":"2-1/2 ft.","reach":"0 ft.","strength":5,"dexterity":15,"constitution":10,"intelligence":2,"wisdom":12,"charisma":5,"baseatk":0,"cmb":0,"cmd":7,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":9},{"skill":"Stealth","value":10},{"skill":"Swim","value":6}],"environments":["temperate forests"],"organizations":["solitary","pair","family (1 adult plus 1-4 young)"],"treasure":"incidental","description_visual":"This animal is about the size of a small dog. Its fur is brownish-grey, and its bushy tail is ringed in black. Its paws and ears are black as well, and it has a black and white mask-like marking on its face.","source":"Tome of Horrors Complete (3pp)","description":"Raccoons are small nocturnal omnivores that live in all but the warmest and coldest forests. They prefer to dwell near lakes and rivers, where their primary nourishment consists of fresh-water shellfish, frogs, lizards, and berries. Males often travel up to four or five miles from the lair in search of food while females tend to stay closer, especially if there are young raccoons in the den. They make their dens in trees or caves, mines, burrows, buildings, or sewers. Those found in populated areas feed on leftover or discarded food and trash. When food is scarce, raccoons in any environment often resort to eating the remains of dead animals. Raccoons mate in the spring, gestation usually lasts about 60 days, and bear 1d8 live young (only about half of which survive to adulthood) which stay with their mother for about a year. The kits are capable of hunting on their own after only 3 months, however. Females reach maturity after about 1 year; males after about 2 years. Raccoons are smart, curious animals that have a reputation for mischief. It isn't irony that gave the raccoon a bandit-like mask. In combat a raccoon engages in an intimidating display of shrill growls, stamping ft., and puffed up fur. Raccoons have sharp, strong teeth and use them well if cornered. Like all small mammals, however, raccoons prefer to avoid actual combat if at all possible. Familiar As a familiar, a raccoon provides its master with a +3 bonus on Sleight of Hand checks.","ecology":"","habitat_society":""},{"name":"Barrow Rat","cr":0.25,"xp":100,"alignment":"N","size":"Tiny","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 natural, +2 size","hp":5,"hd":"1d10","hdvalue":1,"fort":2,"ref":4,"will":1,"defensive_abilities":["stone skin"],"speed":[{"type":"land","speed":15},{"type":"climb","speed":15},{"type":"burrow","speed":15}],"melee":"bite +5 (1d3-3)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"swarm"}],"strength":4,"dexterity":15,"constitution":11,"intelligence":2,"wisdom":12,"charisma":3,"baseatk":1,"cmb":-4,"cmd":8,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":10},{"skill":"Stealth","value":12}],"environments":["any underground"],"organizations":["pack (4-9)","swarm (11-20)","nest (10-40 plus 100% noncombatant young)"],"treasure":"none","description_visual":"A chattering swarm of large, sickly looking brown rats emerge from everywhere. The creatures appear both half starved and agitated to aggression.","group":"Rat","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Stone Skin","kind":"Su","details":"Once per day, as a standard action, a barrow rat can toughen its skin to the hardness of stone. It gains damage reduction 10/- for 1 minute."},{"type":"Swarm","kind":"Ex","details":"Barrow rats crawl over each other in an attempt to swarm an opponent. Up to four barrow rats can occupy a single 5-foot space."}],"description":"Barrow rats are scavengers by nature and prefer to feed on dead animals or rotting corpses, even going as far as to gnaw through a wooden coffin to eat the flesh of a newly dead and buried creature. Food that isn't immediately devoured is ripped into smaller pieces that can be carried and is whisked back to the barrow rat's nest and stored for later consumption or fed to the newborn barrow rats.\n\nBarrow rats are 15-inch long brownish-gray rats with long gray or brown, hairless tails. Their underbellies are lighter in color than their fur often appearing white in some rare species, but usually appearing light brown or slate. Some barrow rats have a dark brown or black stripe on their dorsal side that runs the length of their body.\n\nBarrow rats are not as numerous or populous as their normal relatives and are generally only encountered near barrow mounds or graveyards. Most encounters are at night as the rats sleep in underground burrows during daylight hours. A typical barrow rat nest holds 10-40 of the creatures with an additional 10-40 noncombatant young. One or two males dominate the nest. Typically there are two or three females that dominate the colony, but remain subordinate to the dominate male(s). Young are born live and a female typically gives birth to 3d8 young. The typical gestation period for a barrow rat is 1 month and young reach maturity in 3 months. Young are born blind and hairless and are completely dependent on their mother for several days thereafter. Young open their eyes around 20 days and the mother weans her young after about one month. Young barrow rats gain the stone skin ability at 30 days after birth.\n\nBarrow rats rarely engage in combat with creatures much larger than themselves, preferring to flee when confronted. Smaller creatures are attacked from ambush and swarmed by the rats.\n\nIf threatened or cornered, a barrow rat activates its stone skin ability for defense and either attacks with its bite or simply flees. Multiple barrow rats swarm an opponent. If their nest or young are threatened, barrow rats fight to the death.","ecology":"","habitat_society":""},{"name":"Deer","cr":0.25,"xp":100,"alignment":"N","size":"Medium","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 dodge, +1 natural","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":5,"will":5,"speed":[{"type":"land","speed":40}],"melee":"gore +2 (1d6+1), 2 hooves -3 (1d4)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":15,"constitution":12,"intelligence":2,"wisdom":14,"charisma":6,"baseatk":1,"cmb":0,"cmd":16,"cmd_special":"can't be tripped","feats":[{"feat":"Dodge","type":"bonus"},{"feat":"Mobility","type":"bonus"},{"feat":"Run"}],"skills":[{"skill":"Acrobatics","value":2,"special":"+6 jump"},{"skill":"Perception","value":10},{"skill":"Stealth","value":10,"special":"+14 in forests"},{"skill":"Swim","value":5}],"environments":["temperate forests"],"organizations":["solitary","mated pair","herd (2-20)"],"treasure":"none","description_visual":"The elegant creature raises it head revealing a majestic rack of antlers. It has a tawny brown hide and small black hooves.","source":"Tome of Horrors Complete (3pp)","description":"Shy and wary, deer range from the arctic to the tropics. They are very flexible creatures, adapting easily to their climate and able to survive in all but the harshest of temperatures. Deer are very flexible in their diets as well, able to exist on plants, insects, fish, and even dead birds. Deer are excellent swimmers and have been known to swim to a distance of five miles in the water. These statistics represent the typical white-tailed deer; they can also be used to represent other deer-like animals such as caribou and antelope. Deer attack with their hooves or antlers. Antelopes, when defending their herd, attack by charging an opponent and butting with their horns (gore). The gore attack only applies to bucks with antlers. Black-Tailed Deer The statistics above can be used to represent the average black-tailed deer as well, with a few minor changes. The black-tailed deer prefers plains, hills, and other open ground as its habitat. It has a +4 racial bonus on Acrobatics checks when jumping. In combat, a black-tailed deer jumps about in an effort to confuse its attackers before stotting (hopping) away.","ecology":"","habitat_society":""},{"name":"Elder Witchlights","cr":0.25,"xp":100,"alignment":"N","size":"Fine","type":"fey","init":4,"senses":[{"type":"low-light vision"}],"ac":21,"ac_touch":21,"ac_flat_footed":18,"ac_mods":"+3 Dex, +8 size","hp":4,"hd":"1d6-2","hdvalue":1,"fort":-2,"ref":5,"will":3,"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":-1,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"prestidigitation"},{"spell":"purify food and drink","details":"1/hour"},{"spell":"virtue"}]}],"strength":1,"dexterity":16,"constitution":6,"intelligence":3,"wisdom":13,"charisma":12,"baseatk":0,"cmb":-5,"cmd":0,"feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Fly","value":19},{"skill":"Perception","value":8},{"skill":"Stealth","value":19}],"languages":["Sylvan (limited)"],"environments":["temperate forests"],"organizations":["solitary","pair","cloud (4-20)","summer swarm (20-100)"],"treasure":"standard","description_visual":"These fey, when young, resemble caterpillars or worms 1/2 in. long with miniscule elven faces. Once they mature they resemble tiny elves no larger than a fat housefly, with moth-like wings on their backs. They emit a beautiful pastel glow, and when doing so at night they appear to be no more than bobbing globes of soft light.","group":"Witchlights","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Glimmer","kind":"Su","details":"Witchlights produce a luminance in their larval stage equal to a candle in brightness. In their adult and elder stage the light is up to half torchlight intensity (bright light in a 10 ft. radius). They can change the intensity or extinguish this light as a free action. The glimmer is a steady, soft glow, and may be silvery-white or just about any color, though the fey that raise them favor pastel shades. Each witchlight has its own unique color which it cannot change."}],"description":"Witchlights are a race of diminutive fey that are bred by pixies and other sylvan creatures to provide illumination and atmosphere to their events. They are born on midsummer in their larval state. In the autumn they spin cocoons for themselves in which they ride out the winter, hatching in early spring in their adult form. As adults, their beating wings release thousands of spores which, when it comes in contact with flower pollen and moonlight, germinate into eggs.\n\nAdult witchlights are vulnerable to cold temperatures, and in all but the warmest climates they die in the fall when the weather turns chilly.\n\nHowever, favored witchlights may be cared for through the harsh winter months; those that survive become elder witchlights. They increase to 1 HD fey, and gain +1 hit point per year of life until they have reached the maximum possible for their hit dice. Elder witchlights have an Intelligence score of 2, which increases to 3 when they reach maximum hit points. The most intelligent witchlights have limited sentience, capable of understanding the sylvan language to a degree and even speaking a few words of it.\n\nFor every point of intelligence an elder witchlight possesses, it gains one of the following spell-like abilities usable at will: stabilize, dancing lights, daze, flare, ghost sound, light, prestidigitation, purify food and drink (1/hour only), or virtue.\n\nLarval and normal witchlights have no combat abilities, and are worth no XP. Elder witchlights may be worth ad-hoc experience (no more than CR 1/4) if they have spell-like abilities usable in combat.\n\nWitchlight Familiars\n\nA witchlight may be taken as a familiar through the Improved Familiar feat. The minimum level to acquire such a familiar is caster level 3. Elder witchlights don't gain additional spell-like abilities for having their intelligence raised due to being a familiar.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Mandrill","cr":0.25,"xp":100,"alignment":"N","size":"Small","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":5,"will":3,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"bite +4 (1d4)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":15,"constitution":12,"intelligence":3,"wisdom":13,"charisma":6,"baseatk":1,"cmb":10,"cmd":20,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":10},{"skill":"Perception","value":5},{"skill":"Stealth","value":10}],"environments":["warm forests"],"organizations":["solitary","foraging pack (2-5)","group (4-9 adults plus 4-10 young)","colony (10-40 adults, plus 15-60 young)"],"treasure":"none","description_visual":"This brightly-colored primate has a bushy mane, dense fur, and a long ridged snout.","source":"Tome of Horrors Complete (3pp)","description":"Mandrills are diurnal and terrestrial primates found in warm forests.\n\nDuring the day, mandrills spend their time on the forest floor, hunting and foraging. At night, the animals seek shelter and refuge in the trees.\n\nThey subsist on a diet of fruits, nuts, berries, small insects, seeds, roots, and occasionally grass and the typical group has a hunting ground of 5-8 square miles. When foraging, mandrills use their powerful hands aid in pulling bulbs and digging roots. A mandrill is equipped with cheek pouches that begin to the side of its teeth and extend down its neck. The animal can hold almost an entire meal in its pouches. It often stores food in its cheeks while it continues to hunt or climb.\n\nA typical mandrill group consists of one or more males, one of which is an alpha male, several females, and an equal number of young (that don't fight). Females have a gestation period of about 5-1/2 months and young are born live (usually in the late winter or early spring months).\n\nYoung generally stay with their mother for about a year (females usually a bit longer, males not quite as long).\n\nThe average adult mandrill reaches a height of just under 3 ft. tall and weighs around 35 pounds (though some males generally weigh around 50 pounds). A mandrill's fur is olive brown fading to a paler color on its underbelly. Adult males have a bright blue and red snout and a yellowish \"beard.\" Females and young mandrills are likewise colored, but their colorations are duller.\n\nMandrills are generally passive creatures and rarely engage in battle, preferring to outmaneuver would-be-attackers by taking to the trees and outrunning their opponents. If the young are threatened, they don't hesitate to attack. Mandrills defending their group always fight to the death. Likewise, a foraging pack that is molested defends its \"treasure\" if food is scarce; otherwise, it usually drops its food (or sticks it in its cheek pouches) and scurries into the trees.","ecology":"","habitat_society":""},{"name":"Muckdweller","cr":0.25,"xp":100,"alignment":"N","size":"Small","type":"magical beast","subtypes":["reptilian"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":5,"hd":"1d10","hdvalue":1,"fort":2,"ref":4,"will":1,"speed":[{"type":"land","speed":10},{"type":"swim","speed":30}],"melee":"bite +4 (1d4-2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blinding spray"}],"strength":6,"dexterity":14,"constitution":11,"intelligence":9,"wisdom":12,"charisma":6,"baseatk":1,"cmb":2,"cmd":9,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Perception","value":5},{"skill":"Swim","value":14}],"environments":["temperate marshes"],"organizations":["pack (3-7)","swarm (8-17)"],"treasure":"standard","description_visual":"This small dwarf-sized bipedal lizard has mottled gray and brown flesh with a short dorsal fin that runs the length of its body, tapering off as it meets the tail. Its underbelly is yellow and its eyes are white. Its ft. are webbed as are its tiny  \"hands.\"","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Blinding Spray","kind":"Ex","details":"By filling its mouth with muddy water, a muckdweller can fire a stream of muddy water in a 10-foot line. A creature hit must succeed on a DC 10 Reflex save or be blinded for 1d2 rounds. The save DC is Constitution-based. A muckdweller can take a move action to refill its mouth with muddy water so it can use its spray again."}],"description":"The muckdweller is a small, swamp-dwelling bipedal lizard that lives on a diet of carrion, fresh meat, plants, and insects. It has a long tail that allows it to swim rapidly through the water or maintain its balance when standing upright. Muckdwellers sometimes associate with lizardfolk.\n\nMuckdwellers stand about 4 ft. tall. They speak their own language of croaks and hisses, and a rare few speak Draconic.\n\nThe muckdweller attacks by squirting muddy water at its foes. When it successfully blinds an opponent, it darts in and bites with its sharp teeth.","ecology":"","habitat_society":"","credit":"The Muckdweller originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Sheep","cr":0.25,"xp":100,"alignment":"N","size":"Medium","type":"animal","init":1,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 natural","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":4,"will":0,"speed":[{"type":"land","speed":30}],"melee":"bite +1 (1d6)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":13,"constitution":12,"intelligence":1,"wisdom":11,"charisma":4,"baseatk":1,"cmb":1,"cmd":12,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":8}],"environments":["any mountains","any plains","temperate hills"],"organizations":["flock (5-50 plus 1 ram per 10 adults and (2-20 lambs)"],"treasure":"none","description_visual":"Covered in a thick coat of wool, this placid animal has docile eyes as it forages contentedly.","source":"Tome of Horrors Complete (3pp)","description":"The statistics here describe the common sheep and ram. Sheep generally flee from danger and avoid combat if possible. If cornered, they attack by biting.\n\nRams are male sheep and are usually encountered leading a flock.\n\nRams attack using their horns. They become aggressive if the flock is threatened.","ecology":"","habitat_society":""},{"name":"Skull Spider","cr":0.25,"xp":100,"alignment":"N","size":"Tiny","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 Dex, +2 natural, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":2,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":10}],"melee":"sting +0 (1d2-4 plus poison)","space":"5 ft.","reach":"5 ft.","strength":3,"dexterity":15,"constitution":10,"wisdom":10,"charisma":2,"baseatk":0,"cmb":0,"cmd":6,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":14}],"environments":["any"],"organizations":["Swarm (2-20)"],"treasure":"None","description_visual":"This tiny creature appears to be a humanoid skull with eight spidery legs.","source":"Tome of Horrors Revised (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 10; frequency 1/round for 3 rounds; effect 1 Con; cure 1 save."}],"description":"Skull spiders are tarantula-like creatures that reside in the skulls of their victims. The two front legs of a skull spider contain poisoned barbs that they use to sting their victims.\n\nThe weak and fleshy body of a skull spider is about the size of a grapefruit and is easily damaged. Its eyes grow on the end of long, slender stalks. Skull spiders take up residence within skulls as a means of protecting themselves in a manner similar to hermit crabs.\n\nTheir eyestalks protrude through the empty eye sockets of their skull, and their legs have a backwards curve in the first joint that enables them to extend out of the bottom of the skull to allow rapid locomotion. Skull spiders can also fold their legs under their skull so they cannot be seen. Many an adventurer has been unnerved by the sight of dozens of skulls seemingly sprouting long, spidery legs and skittering toward them.\n\nA colony of skull spiders is led by a king and queen, which are the only two members of the colony that are capable of reproducing. After a victim is subdued, the queen deposits an egg in the skull. Queen skull spiders are always 3 HD. The larva hatches, consumes the brain over a period of weeks, and then enters a pupae stage. After several months, when the corpse is sufficiently deteriorated, the new skull spider hatches, uses its strong legs to detach the skull, and goes to join its colony.","ecology":"","habitat_society":""},{"name":"Skull Spider","cr":0.25,"xp":100,"alignment":"N","size":"Tiny","type":"vermin","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":17,"ac_flat_footed":15,"ac_mods":"+5 Dex, +3 natural, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":5,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":10}],"melee":"sting +0 (1d2-2 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","strength":6,"dexterity":20,"constitution":10,"wisdom":10,"charisma":2,"baseatk":0,"cmb":3,"cmd":11,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":13},{"skill":"Perception","value":4},{"skill":"Stealth","value":13}],"environments":["any"],"organizations":["swarm (2-20)"],"treasure":"none","description_visual":"This tiny creature appears to be a humanoid skull with eight spidery legs.","group":"Spider","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 10; frequency 1/round for 4 rounds, then 1/ten minutes until cured; effect 1d2 Con; cure 2 consecutive saves."}],"description":"Skull spiders are tarantula-like creatures that reside in the skulls of their victims. The two front legs of a skull spider contain poisoned barbs that they use to sting their victims. The weak and fleshy body of a skull spider is about the size of a grapefruit and is easily damaged. Its eyes grow on the end of long, slender stalks. Skull spiders take up residence within skulls as a means of protecting themselves in a manner similar to hermit crabs.\n\nTheir eyestalks protrude through the empty eye sockets of their skull, and their legs have a backwards curve in the first joint that enables them to extend out of the bottom of the skull to allow rapid locomotion. Skull spiders can also fold their legs under their skull so they cannot be seen.\n\nMany an adventurer has been unnerved by the sight of dozens of skulls seemingly sprouting long, spidery legs and skittering toward them.\n\nA colony of skull spiders is led by a king and queen, which are the only two members of the colony that are capable of reproducing. After a victim is subdued, the queen deposits an egg in the skull. Queen skull spiders are always 3 HD. The larva hatches, consumes the brain over a period of weeks, and then enters a pupae stage. After several months, when the corpse is sufficiently deteriorated, the new skull spider hatches, uses its strong legs to detach the skull, and goes to join its colony.\n\nSkull spiders always attack en masse, swarming over their victims in great numbers and stinging them repeatedly.","ecology":"","habitat_society":""}];
